import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.BQq6mqvm.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790385461000}'),s={name:"guide/faq.md"};function l(i,a,n,c,d,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="打开页面提示「无法在此网络下使用-请更换网络再试-」" tabindex="-1">打开页面提示「无法在此网络下使用，请更换网络再试！」 <a class="header-anchor" href="#打开页面提示「无法在此网络下使用-请更换网络再试-」" aria-label="Permalink to &quot;打开页面提示「无法在此网络下使用，请更换网络再试！」&quot;">​</a></h2><p>这是系统检测到<strong>当前网络访问不到服务端接口</strong>。</p><p>按顺序检查：</p><ol><li><strong>是不是没连公司网络？</strong> 连上公司网络或 VPN 后再试。</li><li><strong>网页端配置的接口地址对吗？</strong> 用前后端分离部署时，检查网页端容器的 <code>LANDRIVE_API_BASE_URL</code> 是否指向了内网可达的地址。</li><li><strong>服务端放行网页端地址了吗？</strong> 服务端的 <code>LANDRIVE_CORS_ALLOW</code> 必须等于用户浏览器里打开的网页地址。</li><li><strong>服务端还活着吗？</strong> 在服务器上执行 <code>curl http://127.0.0.1:8080/api/health</code>，返回 <code>&quot;status&quot;:&quot;ok&quot;</code> 才算正常。</li></ol><div class="tip custom-block"><p class="custom-block-title">怎么区分是网络问题还是密码问题？</p><ul><li>提示「无法在此网络下使用」→ 请求根本没到服务器，是网络或跨域问题。</li><li>提示「工号或密码错误」→ 请求到了服务器，网络没问题，是账号问题。</li></ul></div><h2 id="忘记了管理员密码" tabindex="-1">忘记了管理员密码 <a class="header-anchor" href="#忘记了管理员密码" aria-label="Permalink to &quot;忘记了管理员密码&quot;">​</a></h2><p>用环境变量重置：把 <code>LANDRIVE_ADMIN_PASSWORD</code> 改成一个新值，然后<strong>删除该账号</strong>再重启。</p><div class="warning custom-block"><p class="custom-block-title">只在首次启动生效</p><p><code>LANDRIVE_ADMIN_PASSWORD</code> 只在账号不存在时用于创建账号。如果管理员账号已经存在，改这个变量不会生效。</p></div><p>如果系统里还有其他管理员，直接用另一个管理员账号登录，在<strong>用户管理</strong>里重置即可。</p><h2 id="上传时提示「该文件类型不被允许上传」" tabindex="-1">上传时提示「该文件类型不被允许上传」 <a class="header-anchor" href="#上传时提示「该文件类型不被允许上传」" aria-label="Permalink to &quot;上传时提示「该文件类型不被允许上传」&quot;">​</a></h2><p>管理员在<strong>系统管理</strong>里限制了允许的文件类型。到该页把类型列表清空，即可恢复为允许全部类型。</p><h2 id="上传时提示文件过大" tabindex="-1">上传时提示文件过大 <a class="header-anchor" href="#上传时提示文件过大" aria-label="Permalink to &quot;上传时提示文件过大&quot;">​</a></h2><p>同样在<strong>系统管理</strong>里调整「单文件上限」。这个限制在上传开始前就会校验，所以不会先占用磁盘再失败。</p><h2 id="旧版-office-文件-doc-xls-ppt-无法预览" tabindex="-1">旧版 Office 文件（.doc / .xls / .ppt）无法预览 <a class="header-anchor" href="#旧版-office-文件-doc-xls-ppt-无法预览" aria-label="Permalink to &quot;旧版 Office 文件（.doc / .xls / .ppt）无法预览&quot;">​</a></h2><p>这三种是旧版二进制格式，浏览器无法直接解析。用 Office 打开后<strong>另存为</strong> <code>.docx</code> / <code>.xlsx</code> / <code>.pptx</code>，重新上传即可在线预览。</p><h2 id="视频无法拖动进度条" tabindex="-1">视频无法拖动进度条 <a class="header-anchor" href="#视频无法拖动进度条" aria-label="Permalink to &quot;视频无法拖动进度条&quot;">​</a></h2><p>通过反向代理（如 Nginx）访问时，需要透传 <code>Range</code> 请求头，Nginx 默认支持。如果自定义过配置，请确认没有禁用该请求头。</p><h2 id="文件突然不见了" tabindex="-1">文件突然不见了 <a class="header-anchor" href="#文件突然不见了" aria-label="Permalink to &quot;文件突然不见了&quot;">​</a></h2><p>很可能是<strong>到期自动清理</strong>了。上传的文件默认保留 15 天，到期后会移入回收站，此时普通用户和上传者都看不到。</p><p>管理员可以在<strong>文件与回收站</strong>页面找到并恢复。如果连回收站也没有，说明已经超过保留期被彻底删除。</p><p>需要更长的保留时间，请让管理员在<strong>系统管理</strong>里调整天数。</p><h2 id="分片上传中途断网了-怎么办" tabindex="-1">分片上传中途断网了，怎么办？ <a class="header-anchor" href="#分片上传中途断网了-怎么办" aria-label="Permalink to &quot;分片上传中途断网了，怎么办？&quot;">​</a></h2><p>不用做任何处理，<strong>接着传就行</strong>。已经传完的分片不会重传，页面刷新后也能继续。</p><p>如果放置太久（超过 24 小时没有动作），服务端会清理掉这次上传的临时分片，此时重新上传即可。</p><h2 id="忘记密码了" tabindex="-1">忘记密码了 <a class="header-anchor" href="#忘记密码了" aria-label="Permalink to &quot;忘记密码了&quot;">​</a></h2><p>系统暂不支持自助找回。请联系管理员，在<strong>用户管理</strong>里为你重置密码。</p><p>重置后你原来登录的设备会立即失效，需要用新密码重新登录。</p><h2 id="在哪里看谁下载或删除了文件" tabindex="-1">在哪里看谁下载或删除了文件？ <a class="header-anchor" href="#在哪里看谁下载或删除了文件" aria-label="Permalink to &quot;在哪里看谁下载或删除了文件？&quot;">​</a></h2><p>本系统不记录操作日志，无法追溯历史操作。</p>',30)])])}const g=o(s,[["render",l]]);export{u as __pageData,g as default};
